def longest_palindrome(s):
    text = str(s or '')
    if len(text) < 2:
        return text

    def expand(left, right):
        while left >= 0 and right < len(text) and text[left] == text[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    best_left, best_right = 0, 0
    for center in range(len(text)):
        l1, r1 = expand(center, center)          # 奇数长度
        l2, r2 = expand(center, center + 1)      # 偶数长度
        if r1 - l1 > best_right - best_left:
            best_left, best_right = l1, r1
        if r2 - l2 > best_right - best_left:
            best_left, best_right = l2, r2
    return text[best_left:best_right + 1]


print(longest_palindrome('babad'))
print(longest_palindrome('cbbd'))
print(longest_palindrome('a'))
